{
  "implementation": "import heapq

def solve(case):
    nodes = {}  # id -> node
    children = {}  # parent_id -> list of child ids
    for node in case['nodes']:
        nid = node['id']
        nodes[nid] = node
        pid = node['parent']
        if pid is not None:
            children.setdefault(pid, []).append(nid)

    required_symbols = set(case['required_symbols'])

    retained = set(nodes.keys())
    child_count_retained = {}
    for nid, node in nodes.items():
        cnt = 0
        for child in children.get(nid, []):
            if child in retained:
                cnt += 1
        child_count_retained[nid] = cnt

    symbol_count = {}
    for sym in required_symbols:
        symbol_count[sym] = sum(1 for node in nodes.values() if node['symbol'] == sym and node['id'] in retained)

    heap = []
    for nid, node in nodes.items():
        if node['removable'] and node['parent'] is not None and child_count_retained[nid] == 0 and nid in retained:
            heapq.heappush(heap, (-node['depth'], nid))

    removed_node_ids = []

    while heap:
        neg_depth, nid = heapq.heappop(heap)
        if nid not in retained:
            continue
        node = nodes[nid]
        if child_count_retained[nid] != 0:
            continue
        if not node['removable']:
            continue
        sym = node['symbol']
        ok = True
        if sym in required_symbols and symbol_count[sym] - 1 < 1:
            ok = False
        if not ok:
            continue
        # proceed with removal
        removed_node_ids.append(nid)
        retained.discard(nid)
        if sym in required_symbols:
            symbol_count[sym] -= 1
        pid = node['parent']
        if pid is not None:
            child_count_retained[pid] -= 1
            if child_count_retained[pid] == 0:
                pnode = nodes[pid]
                if pnode['removable'] and pid in retained:
                    heapq.heappush(heap, (-pnode['depth'], pid))

    retained_node_ids = sorted(retained)
    return {
        'removed_node_ids': removed_node_ids,
        'retained_node_ids': retained_node_ids
    }"
}
